#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    long long low = 1, high = n;
    while (low < high) {
        long long mid = low + (high - low) / 2;
        __int128 triangular = (__int128)mid * (mid + 1) / 2;

        if (triangular >= n)
            high = mid;
        else
            low = mid + 1;
    }

    long long previous = (long long)((__int128)(low - 1) * low / 2);
    cout << n - previous;

    return 0;
}

